"use client"

import * as React from "react"
import { Combobox as BaseCombobox } from "@base-ui/react/combobox"
import { motion, useReducedMotion } from "motion/react"
import { Check, ChevronsUpDown, Search, X } from "lucide-react"

import { cn } from "@/lib/utils"
import { springs, fades, depth, reduced } from "@/lib/motion"
import { buttonVariants } from "./button"

/**
 * Combobox — a filterable input bound to a listbox popup. Built on Base UI's
 * Combobox (which owns filtering, keyboard nav, and selection); seamui styles
 * it as a debossed entry field opening an overlay-depth popup of embossed
 * items. See the seamui design language: type *into* the well, pick a raised key.
 *
 * Aliased directly so the generic `<Value, Multiple>` signature (and the
 * `items` / `value` / `multiple` inference it drives) passes through intact.
 */
const Combobox = BaseCombobox.Root

/**
 * The debossed text field. Shows a leading search icon, a trailing chevron,
 * and a Clear button once there's a value to clear.
 */
function ComboboxInput({
  className,
  placeholder,
  showClear = true,
  ...props
}: React.ComponentProps<typeof BaseCombobox.Input> & {
  showClear?: boolean
}) {
  return (
    <div className="relative w-full">
      <Search className="text-muted-foreground pointer-events-none absolute left-3 top-1/2 size-4 -translate-y-1/2" />
      <BaseCombobox.Input
        data-slot="combobox-input"
        placeholder={placeholder}
        className={cn(
          // debossed — the field is carved into the surface (inset well shadow).
          "flex h-10 w-full min-w-0 rounded-md squircle border border-border/60 bg-muted pl-9 pr-16 py-1 text-sm shadow-well outline-none",
          "placeholder:text-muted-foreground selection:bg-primary selection:text-primary-foreground",
          "focus-visible:ring-2 focus-visible:ring-ring/50 focus-visible:border-ring",
          "aria-invalid:border-destructive aria-invalid:ring-2 aria-invalid:ring-destructive/30",
          "disabled:pointer-events-none disabled:opacity-50",
          className
        )}
        {...props}
      />
      <div className="absolute right-2 top-1/2 flex -translate-y-1/2 items-center gap-0.5">
        {showClear && (
          <BaseCombobox.Clear
            data-slot="combobox-clear"
            className={cn(
              buttonVariants({ variant: "ghost", size: "icon" }),
              "text-muted-foreground size-6 rounded-md"
            )}
            aria-label="Clear"
          >
            <X className="size-4" />
          </BaseCombobox.Clear>
        )}
        <BaseCombobox.Icon
          data-slot="combobox-icon"
          className="text-muted-foreground pointer-events-none flex size-6 items-center justify-center"
        >
          <ChevronsUpDown className="size-4" />
        </BaseCombobox.Icon>
      </div>
    </div>
  )
}

/** Portal + Positioner + Popup — the floating list, with overlay-depth motion. */
function ComboboxContent({
  className,
  children,
  sideOffset = 6,
  ...props
}: React.ComponentProps<typeof BaseCombobox.Popup> & { sideOffset?: number }) {
  const reduceMotion = useReducedMotion()

  return (
    <BaseCombobox.Portal>
      <BaseCombobox.Positioner sideOffset={sideOffset} className="z-50">
        <BaseCombobox.Popup
          data-slot="combobox-content"
          className={cn(
            "bg-popover text-popover-foreground z-50 max-h-[min(24rem,var(--available-height))] w-[var(--anchor-width)] overflow-y-auto overscroll-contain rounded-lg squircle border p-1 shadow-overlay outline-none",
            className
          )}
          // seam motion: floating surface rises with overlay depth.
          render={
            <motion.div
              initial={reduceMotion ? reduced.fadeIn.initial : depth.overlay.initial}
              animate={depth.overlay.animate}
              transition={reduceMotion ? fades.normal : springs.surface}
            />
          }
          {...props}
        >
          {children}
        </BaseCombobox.Popup>
      </BaseCombobox.Positioner>
    </BaseCombobox.Portal>
  )
}

/**
 * The list. Pass a render function as the child to map over filtered items:
 * `<ComboboxList>{(item) => <ComboboxItem value={item}>{item.label}</ComboboxItem>}</ComboboxList>`
 */
function ComboboxList({
  className,
  ...props
}: React.ComponentProps<typeof BaseCombobox.List>) {
  return (
    <BaseCombobox.List
      data-slot="combobox-list"
      className={cn("outline-none", className)}
      {...props}
    />
  )
}

function ComboboxItem({
  className,
  children,
  ...props
}: React.ComponentProps<typeof BaseCombobox.Item>) {
  return (
    <BaseCombobox.Item
      data-slot="combobox-item"
      className={cn(
        "relative flex cursor-default select-none items-center gap-2 rounded-md squircle py-1.5 pl-2 pr-8 text-sm outline-none",
        "data-[highlighted]:bg-accent data-[highlighted]:text-accent-foreground",
        "data-[disabled]:pointer-events-none data-[disabled]:opacity-50",
        className
      )}
      {...props}
    >
      {children}
      <BaseCombobox.ItemIndicator className="absolute right-2 flex items-center">
        <Check className="size-4" />
      </BaseCombobox.ItemIndicator>
    </BaseCombobox.Item>
  )
}

/** Shown only when the filter yields no matches. */
function ComboboxEmpty({
  className,
  ...props
}: React.ComponentProps<typeof BaseCombobox.Empty>) {
  return (
    <BaseCombobox.Empty
      data-slot="combobox-empty"
      // Base UI keeps this element mounted (for screen-reader announcements)
      // and only renders children when the list is actually empty. `empty:`
      // collapses its padding to zero height while there are matches, so it
      // doesn't leave a gap at the top of the popup.
      className={cn(
        "text-muted-foreground py-6 text-center text-sm empty:py-0",
        className
      )}
      {...props}
    />
  )
}

function ComboboxGroup(props: React.ComponentProps<typeof BaseCombobox.Group>) {
  return <BaseCombobox.Group data-slot="combobox-group" {...props} />
}

/** Renders the filtered items within a group. See the Groups example. */
const ComboboxCollection = BaseCombobox.Collection

function ComboboxGroupLabel({
  className,
  ...props
}: React.ComponentProps<typeof BaseCombobox.GroupLabel>) {
  return (
    <BaseCombobox.GroupLabel
      data-slot="combobox-group-label"
      className={cn(
        "px-2 py-1.5 text-xs font-medium text-muted-foreground",
        className
      )}
      {...props}
    />
  )
}

// Base UI's Combobox has no Separator part, so this is a plain divider.
function ComboboxSeparator({
  className,
  ...props
}: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="combobox-separator"
      role="separator"
      className={cn("bg-border -mx-1 my-1 h-px", className)}
      {...props}
    />
  )
}

/* ── Multi-select (chips) ────────────────────────────────────────────────
   For `multiple` comboboxes: a debossed well that wraps selected values as
   embossed chips alongside the input. Compose as
   <ComboboxChips>
     <ComboboxValue>{(items) => items.map((i) => <ComboboxChip …/>)}</ComboboxValue>
     <ComboboxChipsInput placeholder="…" />
   </ComboboxChips>
*/

/**
 * The debossed well that holds chips + the input in multi-select mode.
 * Wrapped in Base UI's InputGroup so the popup anchors to (and matches the
 * width of) the whole well — not the bare input, which would otherwise pin
 * the dropdown to the caret and squeeze it to the input's width.
 */
function ComboboxChips({
  className,
  ...props
}: React.ComponentProps<typeof BaseCombobox.Chips>) {
  return (
    <BaseCombobox.InputGroup className="w-full">
      <BaseCombobox.Chips
        data-slot="combobox-chips"
        className={cn(
          "flex min-h-10 w-full flex-wrap items-center gap-1.5 rounded-md squircle border border-border/60 bg-muted px-2 py-1.5 text-sm shadow-well outline-none",
          "focus-within:ring-2 focus-within:ring-ring/50 focus-within:border-ring",
          "has-aria-invalid:border-destructive has-aria-invalid:ring-2 has-aria-invalid:ring-destructive/30",
          className
        )}
        {...props}
      />
    </BaseCombobox.InputGroup>
  )
}

/** Reads the selected value(s); pass a render function to map them to chips. */
const ComboboxValue = BaseCombobox.Value

/** An embossed pill representing one selected value. */
function ComboboxChip({
  className,
  children,
  ...props
}: React.ComponentProps<typeof BaseCombobox.Chip>) {
  return (
    <BaseCombobox.Chip
      data-slot="combobox-chip"
      className={cn(
        "bg-secondary text-secondary-foreground shadow-resting flex items-center gap-1 rounded-md squircle py-0.5 pl-2 pr-1 text-xs font-medium outline-none",
        "data-[highlighted]:ring-2 data-[highlighted]:ring-ring/50",
        className
      )}
      {...props}
    >
      {children}
    </BaseCombobox.Chip>
  )
}

function ComboboxChipRemove({
  className,
  ...props
}: React.ComponentProps<typeof BaseCombobox.ChipRemove>) {
  return (
    <BaseCombobox.ChipRemove
      data-slot="combobox-chip-remove"
      className={cn(
        buttonVariants({ variant: "ghost", size: "icon" }),
        "text-muted-foreground size-4 rounded-sm",
        className
      )}
      aria-label="Remove"
      {...props}
    >
      <X className="size-3" />
    </BaseCombobox.ChipRemove>
  )
}

/** A bare input sized to sit inside the chips well (no icons/affordances). */
function ComboboxChipsInput({
  className,
  ...props
}: React.ComponentProps<typeof BaseCombobox.Input>) {
  return (
    <BaseCombobox.Input
      data-slot="combobox-chips-input"
      className={cn(
        "placeholder:text-muted-foreground min-w-16 flex-1 bg-transparent outline-none",
        className
      )}
      {...props}
    />
  )
}

export {
  Combobox,
  ComboboxInput,
  ComboboxContent,
  ComboboxList,
  ComboboxItem,
  ComboboxEmpty,
  ComboboxGroup,
  ComboboxGroupLabel,
  ComboboxCollection,
  ComboboxSeparator,
  ComboboxChips,
  ComboboxChip,
  ComboboxChipRemove,
  ComboboxChipsInput,
  ComboboxValue,
}
